import math

def is_prime(n):
    if n <= 1:
        return False       # 0 and 1 are not prime
    if n == 2:
        return True        # 2 is the only even prime
    if n % 2 == 0:
        return False       # other even numbers are not prime
    for i in range(3, int(math.sqrt(n)) + 1, 2):  # check odd divisors up to sqrt
        if n % i == 0:
            return False
    return True

for num in [2, 7, 15, 23, 49]:
    print(f'{num}: {is_prime(num)}')
